"""1-bit bitmap glyphs rasterized from the DejaVu family (free license).

Each variant maps to a base64 blob. A blob holds one record per ASCII
printable character (32..126), in order: char(1B) advance(1B) width(1B)
height(1B) dx(1B, signed) dy(1B, signed) then ceil(w*h/8) bitmap bytes,
MSB-first. dx is the ink left edge relative to the pen position, dy is
the ink top relative to the ascender line. Generated at build time; the
entry program is stdlib-only and only decodes this data."""

FONTS = {
    "serif_bold_40": "",
    "sans_bold_22": "",
    "sans_bold_14": "",
    "sans_bold_12": "",
    "sans_bold_11": "",
    "sans_13": "",
    "sans_12": "",
    "sans_11": "",
    "sans_10": "",
    "sans_9": "",
}

CHARS = "".join(chr(c) for c in range(32, 127))


def load(name):
    """Decode one variant into {char: (advance, dx, dy, w, h, bitmap)}."""
    import base64
    import struct
    raw = base64.b64decode(FONTS[name])
    glyphs = {}
    i = 0
    while i < len(raw):
        code, adv, w, h, dx = struct.unpack_from('BBBBb', raw, i)
        dy = struct.unpack_from('b', raw, i + 5)[0]
        i += 6
        nbytes = (w * h + 7) // 8
        glyphs[chr(code)] = (adv, dx, dy, w, h, raw[i:i + nbytes])
        i += nbytes
    return glyphs
